option.value:
import api from './api';

export const attemptService = {
  startAttempt: (examId) => api.post(`/api/attempt/start/${examId}`),
  getAttemptByExam: (examId) => api.get(`/api/attempt/exam/${examId}`),
  getResponses: (attemptId) => api.get(`/api/attempt/${attemptId}/responses`),
  submitResponse: (attemptId, payload) => api.post(`/api/attempt/${attemptId}/response`, payload),
  submitAttempt: (attemptId) => api.post(`/api/attempt/${attemptId}/submit`),
  getAttemptById: (attemptId) => api.get(`/api/attempt/${attemptId}`),
};
